        emon.Testport.assertEq(emon.Port.cellsAt(source, quad + 5), 960, "20 pixels is 9.6 points");
        emon.Testport.assertEq(emon.Port.cellsAt(source, cls), 1, "classifier decision");
        emon.Testport.assertEq(emon.Port.cellsAt(source, cls + 1), 900, "per-mille confidence is not a length");
